#pragma once
#include "PluginProcessor.h"
#include "ParameterGraphics.h"
struct RackKnob:juce::Component {
 SynthMavenProcessor&p;int index,layer;juce::Label label;juce::Slider slider;std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment>attachment;
 RackKnob(SynthMavenProcessor&proc,int n,const juce::String&name):p(proc),index(n),layer(proc.selectedLayer.load()){addAndMakeVisible(label);label.setText(name,juce::dontSendNotification);label.setJustificationType(juce::Justification::centred);label.setFont(10);label.setColour(juce::Label::textColourId,juce::Colour(0xff8394a7));addAndMakeVisible(slider);slider.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);slider.setTextBoxStyle(juce::Slider::TextBoxBelow,false,74,18);slider.setRange(0,1);slider.setColour(juce::Slider::textBoxOutlineColourId,juce::Colours::transparentBlack);slider.setDoubleClickReturnValue(true,OscillatorRack::defaults[n]);attachment=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.parameters,p.layerId(layer,OscillatorRack::keys[n]),slider);slider.textFromValueFunction=[n](double v){if(n==3||n==9)return juce::String(juce::roundToInt(v*6)-3)+" oct";if(n==4||n==10)return juce::String(juce::roundToInt((v-.5)*200))+" ct";if(n==18||n==21)return juce::String(.05+v*v*4,2)+" Hz";if(n==23)return juce::String((v-.5)*160,0)+"%";if(n==13)return juce::String(1+v*v*4000,0)+" ms";if(n==14)return juce::String(5+v*v*4000,0)+" ms";if(n==16)return juce::String(5+v*v*6000,0)+" ms";return juce::String(v*100,0)+"%";};slider.updateText();}
 void resized()override{label.setBounds(0,0,getWidth(),18);slider.setBounds(0,18,getWidth(),getHeight()-18);}
};
struct OscillatorPanel:juce::Component {
 SynthMavenProcessor&p;int layer;bool effects;ParameterGraphic envelope,chorusGraph,flangerGraph;juce::OwnedArray<RackKnob>knobs;juce::OwnedArray<juce::ToggleButton>enabled;juce::OwnedArray<juce::ComboBox>waves;std::vector<std::unique_ptr<juce::AudioProcessorValueTreeState::ButtonAttachment>>buttons;
 OscillatorPanel(SynthMavenProcessor&proc,bool fx=false):p(proc),layer(proc.selectedLayer.load()),effects(fx),envelope(proc,ParameterGraphic::Envelope,13,ParameterGraphic::Rack),chorusGraph(proc,ParameterGraphic::ModDelay,17,ParameterGraphic::Rack),flangerGraph(proc,ParameterGraphic::ModDelay,20,ParameterGraphic::Rack){if(fx){addAndMakeVisible(chorusGraph);addAndMakeVisible(flangerGraph);}else addAndMakeVisible(envelope);
  auto add=[&](int i,const char*name){addAndMakeVisible(knobs.add(new RackKnob(p,i,name)));};
  if(fx){add(17,"Mix");add(18,"Rate");add(19,"Depth");add(20,"Mix");add(21,"Rate");add(22,"Depth");add(23,"Feedback");return;}
  add(0,"Source level");for(int osc=0;osc<2;osc++){int k=1+osc*6;auto*t=enabled.add(new juce::ToggleButton("ON"));addAndMakeVisible(t);buttons.push_back(std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.parameters,p.layerId(layer,OscillatorRack::keys[k]),*t));auto*c=waves.add(new juce::ComboBox());addAndMakeVisible(c);c->addItemList({"Sine","Saw","Square","Triangle"},1);c->setSelectedItemIndex(juce::roundToInt(raw(k+1)*3));c->onChange=[this,c,k]{auto*q=p.parameters.getParameter(p.layerId(layer,OscillatorRack::keys[k+1]));q->beginChangeGesture();q->setValueNotifyingHost(c->getSelectedItemIndex()/3.f);q->endChangeGesture();};add(k+2,"Octave");add(k+3,"Fine");add(k+4,"Level");add(k+5,"Pan");}add(13,"Attack");add(14,"Decay");add(15,"Sustain");add(16,"Release");
 }
 float raw(int n)const{return p.parameters.getRawParameterValue(p.layerId(layer,OscillatorRack::keys[n]))->load();}
 void refresh(){envelope.repaint();chorusGraph.repaint();flangerGraph.repaint();for(int osc=0;osc<waves.size();osc++)waves[osc]->setSelectedItemIndex(juce::roundToInt(raw(2+osc*6)*3),juce::dontSendNotification);repaint();}
 void paint(juce::Graphics&g)override{using namespace juce;g.setColour(Colour(0xff101923));g.fillRoundedRectangle(getLocalBounds().toFloat(),7);g.setFont(Font(12,Font::bold));g.setColour(Colour(0xff56e5c7));if(effects){g.drawText("STEREO CHORUS / POST SOURCE MIX",16,8,getWidth()/2-24,22,Justification::centredLeft);g.drawText("STEREO FLANGER / POST CHORUS",getWidth()/2+12,8,getWidth()/2-24,22,Justification::centredLeft);return;}
  int cw=getWidth()/3;g.drawText("OSC 1 / ENGINE SOURCE",14,8,cw-28,20,Justification::centredLeft);g.setColour(Colour(0xff8394a7));g.setFont(12);g.drawFittedText(p.layerInstrument(layer)+"\n"+p.displayName(layer),14,42,cw-28,64,Justification::centred,3);g.setFont(10);g.drawFittedText("Original engine / sampler architecture\nOSC 2 + 3 add independent pitched voices",14,122,cw-28,42,Justification::centred,3);
  for(int osc=0;osc<2;osc++){int x=(osc+1)*cw,k=1+osc*6;g.setColour(Colour(0xff56e5c7));g.setFont(Font(12,Font::bold));g.drawText("OSC "+String(osc+2)+" / WAVE OSCILLATOR",x+14,8,cw-90,22,Justification::centredLeft);Rectangle<float>r((float)x+16,42,(float)cw-32,76);g.setColour(Colour(0xff243442));g.drawHorizontalLine((int)r.getCentreY(),r.getX(),r.getRight());Path path;for(int n=0;n<=200;n++){float px=n/200.f,y=OscillatorRack::wave(std::fmod(px*2,.999999),.001,roundToInt(raw(k+1)*3));Point<float>pt(r.getX()+px*r.getWidth(),r.getCentreY()-y*r.getHeight()*.42f);if(n==0)path.startNewSubPath(pt);else path.lineTo(pt);}g.setColour(Colour(0xff56e5c7).withAlpha(raw(k)>=.5f?1.f:.35f));g.strokePath(path,PathStrokeType(2));}
  g.setColour(Colour(0xff8394a7));g.setFont(11);g.drawText("OSC 2 + 3 / SHARED AMPLITUDE ENVELOPE",16,350,getWidth()-32,22,Justification::centredLeft);
 }
 void resized()override{int cw=getWidth()/3;if(effects){chorusGraph.setBounds(12,34,getWidth()/2-24,160);flangerGraph.setBounds(getWidth()/2+12,34,getWidth()/2-24,160);for(int i=0;i<knobs.size();i++){int x=i<3?16+i*(getWidth()/2-24)/3:getWidth()/2+8+(i-3)*(getWidth()/2-20)/4;knobs[i]->setBounds(x,206,(getWidth()/2-24)/(i<3?3:4),110);}return;}knobs[0]->setBounds((cw-100)/2,190,100,114);int ci=1;for(int osc=0;osc<2;osc++){int x=(osc+1)*cw;enabled[osc]->setBounds(x+cw-66,8,58,26);waves[osc]->setBounds(x+16,130,cw-32,30);for(int n=0;n<4;n++)knobs[ci++]->setBounds(x+10+(n%2)*(cw-20)/2,174+(n/2)*86,(cw-20)/2,84);}envelope.setBounds(16,378,getWidth()-32,160);for(int n=0;n<4;n++)knobs[ci++]->setBounds(16+n*(getWidth()-32)/4,550,(getWidth()-32)/4,100);}
};
